fn fibonacci(n: usize) -> Vec<i32> {
    // Create a vector with capacity n for efficiency
    let mut result = Vec::with_capacity(n);
    
    // Handle the base cases
    if n >= 1 {
        result.push(0);  // F(0)
    }
    if n >= 2 {
        result.push(1);  // F(1)
    }
    
    // Generate the rest of the sequence
    for i in 2..n {
        // The problem guarantees F(i) < 2^31, so this addition won't overflow
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}